// POS's own minimal service worker -- hand-written, not generated by
// vite-plugin-pwa (see web/vite.config.ts's comment on why: that plugin's
// `virtual:pwa-register` module has no per-instance scoping, so a second
// VitePWA() instance for POS would race Minions' existing one over which
// wins the import). Registered with an explicit narrow scope
// (pos-main.tsx: `{ scope: "/pos.html" }`) so it can never intercept
// fetches for the main shell or Minions, even though all three are
// served from one origin.
//
// This only needs to do two things: make POS installable (any
// registered SW + manifest satisfies that), and keep the app shell
// (this page's own JS/CSS/wasm) loadable when offline. The actual sale
// data offline queue is pos-engine's own job (OfflineQueue, Rust/WASM) --
// unrelated to this file, which only ever touches static assets.
//
// Deliberately not a precache list: Vite's build output filenames are
// content-hashed, so a hand-written list would go stale on every
// deploy. Instead, opportunistically cache whatever was actually
// fetched while online, and serve that back when the network fails --
// no knowledge of hashed filenames needed.
const CACHE_NAME = "friday-pos-shell-v1";

self.addEventListener("install", () => {
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k)))),
  );
  self.clients.claim();
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET" || new URL(req.url).origin !== self.location.origin) return;

  event.respondWith(
    fetch(req)
      .then((resp) => {
        if (resp.ok) {
          const copy = resp.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(req, copy));
        }
        return resp;
      })
      .catch(() => caches.open(CACHE_NAME).then((cache) => cache.match(req))),
  );
});
